migas:{list:["6 eggs","6 corn tortillas, torn into pieces (or 2 cups tortilla chips)","1/2 small onion, diced","1 jalapeño or 1/2 bell pepper, diced","1/2 cup shredded cheese","1/2 cup salsa","2 tablespoons oil","1/4 teaspoon salt"],
 steps:["Heat the oil in a skillet over medium high. Fry the tortilla pieces 3 to 4 minutes until crisp.","Add the onion and pepper and cook 2 minutes.","Whisk the eggs with salt, pour in and scramble gently until set.","Top with cheese and salsa."]},
parfait:{list:["2 cups plain or vanilla yogurt","1 1/2 cups frozen berries, thawed (or 1 can fruit, drained)","1/2 cup oats or cereal","2 tablespoons honey"],
 steps:["Spoon 1/4 cup yogurt into each of 4 cups.","Add a layer of fruit.","Repeat the layers.","Top with oats or cereal and a drizzle of honey."]},
bananapancakes:{list:["2 cups pancake mix","1 1/2 cups water (or as the box says)","1 ripe banana, mashed","1 egg","1 tablespoon butter","Syrup for serving"],
 steps:["Stir the pancake mix, water, mashed banana and egg until just combined.","Heat a buttered pan over medium.","Pour 1/4 cup batter per pancake.","Flip when bubbles form on top, about 2 minutes, and cook 1 minute more."]},
beantacos:{list:["8 flour tortillas","1 can (16 oz) refried beans","4 eggs","1/2 cup shredded cheese","1/2 cup salsa","1 tablespoon butter"],
 steps:["Warm the beans in a small pot or the microwave, stirring once.","Scramble the eggs in butter over medium low.","Warm the tortillas.","Fill each with beans, egg, cheese and salsa."]}
